draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var cy = H * 0.46;
var s = Math.min(W / 3, H) ;
var r = Math.min(s * 0.21, H * 0.26);

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var ux = x1 - x0, uy = y1 - y0, m = Math.sqrt(ux * ux + uy * uy);
  ux /= m; uy /= m;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - ux * 8 - uy * 4, y1 - uy * 8 + ux * 4);
  ctx.lineTo(x1 - ux * 8 + uy * 4, y1 - uy * 8 - ux * 4);
  ctx.closePath(); ctx.fill();
}

// ---- 1. sphere
var c1 = W / 6;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(c1, cy, r * 0.42, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.arc(c1, cy, r, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
for (var i = 0; i < 8; i++) {
  var a = i * Math.PI / 4;
  arrow(c1 + Math.cos(a) * r, cy + Math.sin(a) * r,
        c1 + Math.cos(a) * (r + 14), cy + Math.sin(a) * (r + 14), C.rule);
}
ctx.fillStyle = C.ink;
ctx.fillText("sphere, area 4 pi r^2", c1, H - 20);
ctx.fillText("E out everywhere", c1, H - 6);

// ---- 2. coaxial cylinder
var c2 = W / 2;
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(c2, cy - r * 1.25); ctx.lineTo(c2, cy + r * 1.25); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
var cw = r * 0.85, ch = r * 0.75;
ctx.strokeRect(c2 - cw, cy - ch, cw * 2, ch * 2);
ctx.beginPath(); ctx.ellipse(c2, cy - ch, cw, cw * 0.28, 0, 0, Math.PI * 2); ctx.stroke();
ctx.beginPath(); ctx.ellipse(c2, cy + ch, cw, cw * 0.28, 0, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
arrow(c2 + cw, cy, c2 + cw + 16, cy, C.rule);
arrow(c2 - cw, cy, c2 - cw - 16, cy, C.rule);
ctx.fillStyle = C.ink;
ctx.fillText("can, side area 2 pi r L", c2, H - 20);
ctx.fillText("flat ends catch nothing", c2, H - 6);

// ---- 3. pillbox in a sheet
var c3 = 5 * W / 6;
ctx.strokeStyle = C.figure; ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(c3 - r * 1.25, cy); ctx.lineTo(c3 + r * 1.25, cy); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
var pw = r * 0.55, ph = r * 0.6;
ctx.strokeRect(c3 - pw, cy - ph, pw * 2, ph * 2);
ctx.setLineDash([]);
arrow(c3, cy - ph, c3, cy - ph - 16, C.rule);
arrow(c3, cy + ph, c3, cy + ph + 16, C.rule);
ctx.fillStyle = C.ink;
ctx.fillText("pillbox, two faces of area A", c3, H - 20);
ctx.fillText("curved side catches nothing", c3, H - 6);

ctx.textAlign = "left";
